INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.no_endless_in_app_small_talk_once_she_accepts_both_of_your_telegram_ha', 'en', 'No endless in-app small talk! Once she accepts, both of your Telegram handles are securely unlocked so you can chat and plan your date directly.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_is_completely_free_for_all_female_members_you_will_never_be_aske', 'en', 'Amara is completely free for all female members. You will never be asked to pay for invitations, membership, or chatting.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.say_goodbye_to_hundreds_of_unwanted_messages_men_cannot_message_you_di', 'en', 'Say goodbye to hundreds of unwanted messages. Men cannot message you directly; they can only send a formal date invitation for you to review.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.invitations_arrive_in_your_requests_inbox_review_their_verified_profil', 'en', 'Invitations arrive in your Requests Inbox. Review their verified profile, photos, and background. You decide who you want to meet.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_you_accept_an_invite_your_telegram_handle_is_shared_with_your_mat', 'en', 'When you accept an invite, your Telegram handle is shared with your match so you can chat conveniently where you already spend your time.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_are_mens_profiles_hidden_by_default', 'en', 'Why are men’s profiles hidden by default?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_do_matches_move_to_telegram', 'en', 'Why do matches move to Telegram?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.how_does_selfie_verification_work', 'en', 'How does selfie verification work?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.what_is_our_policy_on_sugar_dating_escorting', 'en', 'What is our policy on sugar dating & escorting?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_follows_a_private_luxury_model_many_successful_ambitious_men_val', 'en', 'Amara follows a private luxury model. Many successful, ambitious men value discretion. By hiding male profiles from the public feed, your identity remains private until you choose to invite someone.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.we_believe_dating_should_lead_to_real_life_meetings_not_endless_in_app', 'en', 'We believe dating should lead to real-life meetings, not endless in-app texting. Once mutual interest is confirmed, exchanging Telegram handles allows convenient, encrypted, and direct communication.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.every_member_must_complete_a_real_time_selfie_verification_during_onbo', 'en', 'Every member must complete a real-time selfie verification during onboarding. This guarantees that every profile belongs to an authentic, live human and eliminates catfishing.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_strictly_prohibits_compensated_dating_sugar_arrangements_prostit', 'en', 'Amara strictly prohibits compensated dating, sugar arrangements, prostitution, or any financial exchange between members. Accounts violating these standards are banned permanently.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
