INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.your_profile_is_completely_hidden_from_the_public_feed_women_cannot_se', 'es', 'Tu perfil está completamente oculto del feed público. Las mujeres no pueden buscar ni ver tus fotos salvo que decidas enviarles primero una invitación.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.browse_verified_female_profiles_nearby_or_worldwide_find_someone_you_l', 'es', 'Explora perfiles femeninos verificados cerca de ti o en todo el mundo. Encuentra a alguien que te guste y envíale una invitación directa para una cita (requiere membresía).') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_the_woman_receives_your_invitation_she_reviews_your_profile_photo', 'es', 'Cuando la mujer recibe tu invitación, revisa tu perfil, tus fotos y tu propuesta de cita. Solo ella puede decidir aceptar o rechazar.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.no_endless_in_app_small_talk_once_she_accepts_both_of_your_telegram_ha', 'es', '¡Sin conversaciones interminables en la app! Cuando acepte, los usuarios de Telegram de ambos se desbloquean de forma segura para que puedan chatear y planear la cita directamente.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_is_completely_free_for_all_female_members_you_will_never_be_aske', 'es', 'Amara es totalmente gratuito para todas las miembros. Nunca se te pedirá pagar por invitaciones, membresía o chat.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.say_goodbye_to_hundreds_of_unwanted_messages_men_cannot_message_you_di', 'es', 'Olvídate de cientos de mensajes no deseados. Los hombres no pueden escribirte directamente; solo pueden enviarte una invitación formal para una cita y tú la revisas.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.invitations_arrive_in_your_requests_inbox_review_their_verified_profil', 'es', 'Las invitaciones llegan a tu bandeja de solicitudes. Revisa su perfil verificado, fotos y antecedentes. Tú decides con quién quieres quedar.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_you_accept_an_invite_your_telegram_handle_is_shared_with_your_mat', 'es', 'Cuando aceptas una invitación, tu usuario de Telegram se comparte con tu match para que chateéis cómodamente donde ya pasáis el tiempo.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_are_mens_profiles_hidden_by_default', 'es', '¿Por qué los perfiles de hombres están ocultos por defecto?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
