INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.what_is_our_policy_on_sugar_dating_escorting', 'es', '¿Cuál es nuestra política sobre el sugar dating y el escort?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_follows_a_private_luxury_model_many_successful_ambitious_men_val', 'es', 'Amara sigue un modelo de lujo privado. Muchos hombres exitosos y ambiciosos valoran la discreción. Al ocultar los perfiles masculinos del feed público, tu identidad permanece privada hasta que decidas invitar a alguien.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.we_believe_dating_should_lead_to_real_life_meetings_not_endless_in_app', 'es', 'Creemos que las citas deben desembocar en encuentros reales, no en interminables mensajes dentro de la app. Cuando se confirma el interés mutuo, intercambiar usuarios de Telegram permite una comunicación cómoda, cifrada y directa.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.every_member_must_complete_a_real_time_selfie_verification_during_onbo', 'es', 'Cada miembro debe completar una verificación con selfie en tiempo real durante el registro. Esto garantiza que cada perfil pertenezca a una persona real y auténtica, y elimina el catfishing.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_strictly_prohibits_compensated_dating_sugar_arrangements_prostit', 'es', 'Amara prohíbe estrictamente las citas a cambio de dinero, los acuerdos de sugar, la prostitución y cualquier intercambio financiero entre miembros. Las cuentas que incumplan estas normas serán bloqueadas de forma permanente.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
