INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.your_profile_is_completely_hidden_from_the_public_feed_women_cannot_se', 'pt', 'Seu perfil fica completamente oculto do feed público. Mulheres não podem buscar nem ver suas fotos, a menos que você escolha enviar um convite primeiro.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.browse_verified_female_profiles_nearby_or_worldwide_find_someone_you_l', 'pt', 'Navegue por perfis femininos verificados próximos ou no mundo todo. Encontre alguém que goste e envie um convite direto para um encontro (assinatura necessária).') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_the_woman_receives_your_invitation_she_reviews_your_profile_photo', 'pt', 'Quando a mulher recebe seu convite, ela analisa seu perfil, fotos e proposta de encontro. Somente ela decide aceitar ou recusar.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.no_endless_in_app_small_talk_once_she_accepts_both_of_your_telegram_ha', 'pt', 'Sem conversas intermináveis dentro do app! Quando ela aceitar, os nomes de usuário do Telegram de vocês são desbloqueados com segurança para conversarem e planejarem o encontro direto.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_is_completely_free_for_all_female_members_you_will_never_be_aske', 'pt', 'O Amara é totalmente gratuito para todas as membros mulheres. Você nunca será cobrada por convites, assinatura ou conversas.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.say_goodbye_to_hundreds_of_unwanted_messages_men_cannot_message_you_di', 'pt', 'Diga adeus a centenas de mensagens indesejadas. Homens não podem te enviar mensagens diretamente; eles só podem enviar um convite formal de encontro para você analisar.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.invitations_arrive_in_your_requests_inbox_review_their_verified_profil', 'pt', 'Os convites chegam na sua caixa de solicitações. Analise o perfil verificado, as fotos e o histórico. Você decide com quem quer se encontrar.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_you_accept_an_invite_your_telegram_handle_is_shared_with_your_mat', 'pt', 'Quando você aceita um convite, seu nome de usuário do Telegram é compartilhado com seu match para que vocês conversem com praticidade onde já passam o tempo.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_are_mens_profiles_hidden_by_default', 'pt', 'Por que os perfis de homens ficam ocultos por padrão?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_do_matches_move_to_telegram', 'pt', 'Por que os matches vão para o Telegram?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.how_does_selfie_verification_work', 'pt', 'Como funciona a verificação por selfie?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.what_is_our_policy_on_sugar_dating_escorting', 'pt', 'Qual é a nossa política sobre namoro sugar e acompanhamento?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_follows_a_private_luxury_model_many_successful_ambitious_men_val', 'pt', 'O Amara segue um modelo privado de luxo. Muitos homens bem-sucedidos e ambiciosos valorizam a discrição. Ao ocultar os perfis masculinos do feed público, sua identidade permanece privada até você escolher convidar alguém.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.we_believe_dating_should_lead_to_real_life_meetings_not_endless_in_app', 'pt', 'Acreditamos que o namoro deve levar a encontros na vida real, e não a mensagens intermináveis no app. Quando o interesse mútuo é confirmado, trocar os nomes de usuário do Telegram permite uma comunicação prática, criptografada e direta.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.every_member_must_complete_a_real_time_selfie_verification_during_onbo', 'pt', 'Todo membro deve completar uma verificação de selfie em tempo real durante o cadastro. Isso garante que cada perfil pertença a uma pessoa autêntica e elimina perfis falsos.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_strictly_prohibits_compensated_dating_sugar_arrangements_prostit', 'pt', 'O Amara proíbe estritamente namoro remunerado, acordos sugar, prostituição ou qualquer troca financeira entre membros. Contas que violarem esses padrões são banidas permanentemente.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.privacy_first', 'pt', 'PRIVACIDADE PRIMEIRO') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.invitation_only', 'pt', 'SOMENTE POR CONVITE') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
