INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.browse_verified_female_profiles_nearby_or_worldwide_find_someone_you_l', 'de', 'Durchstöbere verifizierte weibliche Profile in der Nähe oder weltweit. Finde jemanden, der dir gefällt, und sende eine direkte Date-Einladung (Mitgliedschaft erforderlich).') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_the_woman_receives_your_invitation_she_reviews_your_profile_photo', 'de', 'Wenn die Frau deine Einladung erhält, prüft sie dein Profil, deine Fotos und deinen Date-Vorschlag. Nur sie entscheidet über Annahme oder Ablehnung.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.no_endless_in_app_small_talk_once_she_accepts_both_of_your_telegram_ha', 'de', 'Kein endloses Smalltalk in der App! Wenn sie zustimmt, werden beide Telegram-Handles sicher entsperrt, damit ihr chatten und euren Date direkt planen könnt.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_is_completely_free_for_all_female_members_you_will_never_be_aske', 'de', 'Amara ist für alle weiblichen Mitglieder völlig kostenlos. Du wirst nie gebeten, für Einladungen, Mitgliedschaft oder Chatten zu zahlen.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.say_goodbye_to_hundreds_of_unwanted_messages_men_cannot_message_you_di', 'de', 'Verabschiede dich von hunderten unerwünschten Nachrichten. Männer können dir nicht direkt schreiben; sie können nur eine formelle Date-Einladung senden, die du prüfst.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.invitations_arrive_in_your_requests_inbox_review_their_verified_profil', 'de', 'Einladungen kommen in dein Anfragen-Postfach. Prüfe ihr verifiziertes Profil, Fotos und Hintergrund. Du entscheidest, wen du treffen möchtest.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_you_accept_an_invite_your_telegram_handle_is_shared_with_your_mat', 'de', 'Wenn du eine Einladung annimmst, wird dein Telegram-Handle mit deinem Match geteilt, damit ihr bequem dort chatten könnt, wo ihr euch sowieso aufhaltet.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_are_mens_profiles_hidden_by_default', 'de', 'Warum sind Männerprofile standardmäßig verborgen?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
