INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_follows_a_private_luxury_model_many_successful_ambitious_men_val', 'de', 'Amara folgt einem privaten Luxusmodell. Viele erfolgreiche, ambitionierte Männer schätzen Diskretion. Durch das Verbergen männlicher Profile vor dem öffentlichen Feed bleibt deine Identität privat, bis du dich entscheidest, jemanden einzuladen.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.we_believe_dating_should_lead_to_real_life_meetings_not_endless_in_app', 'de', 'Wir glauben, dass Dating zu Treffen im echten Leben führen sollte, nicht zu endlosem Schreiben in der App. Sobald das gegenseitige Interesse bestätigt ist, ermöglicht der Austausch der Telegram-Handles eine bequeme, verschlüsselte und direkte Kommunikation.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.every_member_must_complete_a_real_time_selfie_verification_during_onbo', 'de', 'Jedes Mitglied muss während der Registrierung eine Echtzeit-Selfie-Verifizierung abschließen. Das garantiert, dass jedes Profil einem echten, lebenden Menschen gehört, und eliminiert Catfishing.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_strictly_prohibits_compensated_dating_sugar_arrangements_prostit', 'de', 'Amara verbietet strikt bezahltes Dating, Sugar-Arrangements, Prostitution oder jeden finanziellen Austausch zwischen Mitgliedern. Konten, die diese Standards verletzen, werden dauerhaft gesperrt.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
