INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.your_profile_is_completely_hidden_from_the_public_feed_women_cannot_se', 'fr', 'Ton profil est complètement masqué du fil public. Les femmes ne peuvent ni te rechercher ni voir tes photos, sauf si tu choisis d''abord de leur envoyer une invitation.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.browse_verified_female_profiles_nearby_or_worldwide_find_someone_you_l', 'fr', 'Parcours les profils féminins vérifiés à proximité ou dans le monde entier. Trouve quelqu''un qui te plaît et envoie une invitation directe de rencontre (abonnement requis).') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_the_woman_receives_your_invitation_she_reviews_your_profile_photo', 'fr', 'Quand la femme reçoit ton invitation, elle examine ton profil, tes photos et ta proposition de rencontre. Elle seule décide d''accepter ou de refuser.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.no_endless_in_app_small_talk_once_she_accepts_both_of_your_telegram_ha', 'fr', 'Pas de bavardages interminables dans l''app ! Dès qu''elle accepte, vos identifiants Telegram sont déverrouillés en toute sécurité pour discuter et organiser votre rencontre.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_is_completely_free_for_all_female_members_you_will_never_be_aske', 'fr', 'Amara est totalement gratuit pour toutes les femmes. On ne te demandera jamais de payer pour les invitations, l''abonnement ou les discussions.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.say_goodbye_to_hundreds_of_unwanted_messages_men_cannot_message_you_di', 'fr', 'Dis adieu à des centaines de messages non désirés. Les hommes ne peuvent pas t''écrire directement ; ils peuvent seulement envoyer une invitation formelle de rencontre à ton examen.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.invitations_arrive_in_your_requests_inbox_review_their_verified_profil', 'fr', 'Les invitations arrivent dans ta boîte de demandes. Examine leur profil vérifié, leurs photos et leur historique. Toi, tu décides de qui tu veux rencontrer.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_you_accept_an_invite_your_telegram_handle_is_shared_with_your_mat', 'fr', 'Quand tu acceptes une invitation, ton identifiant Telegram est partagé avec ton match pour discuter facilement là où vous passez déjà votre temps.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_are_mens_profiles_hidden_by_default', 'fr', 'Pourquoi les profils des hommes sont-ils masqués par défaut ?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_do_matches_move_to_telegram', 'fr', 'Pourquoi les correspondances passent-elles sur Telegram ?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.how_does_selfie_verification_work', 'fr', 'Comment fonctionne la vérification par selfie ?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.what_is_our_policy_on_sugar_dating_escorting', 'fr', 'Quelle est notre politique sur les relations sugar et l''escort ?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_follows_a_private_luxury_model_many_successful_ambitious_men_val', 'fr', 'Amara suit un modèle de luxe privé. Beaucoup d''hommes réussis et ambitieux valorisent la discrétion. En masquant les profils masculins du fil public, ton identité reste privée jusqu''à ce que tu choisisses d''inviter quelqu''un.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.we_believe_dating_should_lead_to_real_life_meetings_not_endless_in_app', 'fr', 'Nous pensons que les rencontres doivent mener à des rendez-vous dans la vraie vie, et non à des messages interminables dans l''app. Une fois l''intérêt mutuel confirmé, l''échange des identifiants Telegram permet une communication pratique, chiffrée et directe.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.every_member_must_complete_a_real_time_selfie_verification_during_onbo', 'fr', 'Chaque membre doit effectuer une vérification de selfie en temps réel lors de l''inscription. Cela garantit que chaque profil appartient à une personne authentique et vivante, et élimine les faux profils.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_strictly_prohibits_compensated_dating_sugar_arrangements_prostit', 'fr', 'Amara interdit strictement les rencontres rémunérées, les arrangements sugar, la prostitution ou tout échange financier entre membres. Les comptes violant ces règles sont bannis définitivement.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.privacy_first', 'fr', 'CONFIDENTIALITÉ D''ABORD') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.invitation_only', 'fr', 'SUR INVITATION UNIQUEMENT') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.mutual_interest', 'fr', 'INTÉRÊT MUTUEL') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.direct_contact', 'fr', 'CONTACT DIRECT') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
