INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.your_profile_is_completely_hidden_from_the_public_feed_women_cannot_se', 'ro', 'Profilul tău este complet ascuns din feed-ul public. Femeile nu te pot căuta sau vedea fotografiile decât dacă alegi mai întâi să le trimiți o invitație.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.browse_verified_female_profiles_nearby_or_worldwide_find_someone_you_l', 'ro', 'Răsfoiește profiluri feminine verificate din apropiere sau din toată lumea. Găsește pe cineva pe care îți place și trimite o invitație directă de întâlnire (abonament necesar).') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_the_woman_receives_your_invitation_she_reviews_your_profile_photo', 'ro', 'Când femeia primește invitația ta, ea îți verifică profilul, fotografiile și propunerea de întâlnire. Doar ea decide să accepte sau să refuze.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.no_endless_in_app_small_talk_once_she_accepts_both_of_your_telegram_ha', 'ro', 'Fără discuții interminabile în aplicație! Când acceptă, utilizatorii voștri de Telegram sunt deblocați în siguranță, astfel încât puteți discuta și planifica întâlnirea direct.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_is_completely_free_for_all_female_members_you_will_never_be_aske', 'ro', 'Amara este complet gratuit pentru toate membrele. Nu ți se va cere niciodată să plătești pentru invitații, abonament sau discuții.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.say_goodbye_to_hundreds_of_unwanted_messages_men_cannot_message_you_di', 'ro', 'Spune adio sutelor de mesaje nedorite. Bărbații nu îți pot scrie direct; pot trimite doar o invitație formală de întâlnire pe care să o verifici.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.invitations_arrive_in_your_requests_inbox_review_their_verified_profil', 'ro', 'Invitațiile ajung în Inboxul de solicitări. Verifică profilul lor verificat, fotografiile și istoricul. Tu decizi pe cine vrei să întâlnești.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_you_accept_an_invite_your_telegram_handle_is_shared_with_your_mat', 'ro', 'Când accepți o invitație, utilizatorul tău de Telegram este partajat cu match-ul tău, astfel încât puteți discuta convenabil acolo unde oricum vă petreceți timpul.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_are_mens_profiles_hidden_by_default', 'ro', 'De ce sunt profilele bărbaților ascuse implicit?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_do_matches_move_to_telegram', 'ro', 'De ce se mută potrivirile pe Telegram?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
