INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.what_is_our_policy_on_sugar_dating_escorting', 'ro', 'Care este politica noastră privind întâlnirile de tip sugar și escorta?') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_follows_a_private_luxury_model_many_successful_ambitious_men_val', 'ro', 'Amara urmează un model privat de lux. Mulți bărbați de succes și ambițioși apreciază discreția. Ascunzând profilele bărbaților din feed-ul public, identitatea ta rămâne privată până când alegi să inviți pe cineva.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.we_believe_dating_should_lead_to_real_life_meetings_not_endless_in_app', 'ro', 'Credem că întâlnirile ar trebui să ducă la întâlniri în viața reală, nu la mesaje interminabile în aplicație. Odată ce interesul mutual este confirmat, schimbul de utilizatori Telegram permite o comunicare convenabilă, criptată și directă.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.every_member_must_complete_a_real_time_selfie_verification_during_onbo', 'ro', 'Fiecare membru trebuie să completeze o verificare de selfie în timp real la înregistrare. Acest lucru garantează că fiecare profil aparține unei persoane reale și elimină profilele false.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_strictly_prohibits_compensated_dating_sugar_arrangements_prostit', 'ro', 'Amara interzice strict întâlnirile plătite, aranjamentele de tip sugar, prostituția sau orice schimb financiar între membri. Conturile care încalcă aceste standarde sunt blocate permanent.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
