INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.privacypolicyscreen.welcome_to_amara_we_respect_your_privacy_and_are_committed_to_protecti', 'ro', 'Bine ai venit la Amara. Respectăm confidențialitatea ta și ne angajăm să îți protejăm datele personale. Această politică de confidențialitate îți va spune cum îți păstrăm datele personale când vizitezi aplicația noastră și îți va informa despre drepturile tale de confidențialitate și despre cum te protejează legea.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
