INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.privacypolicyscreen.welcome_to_amara_we_respect_your_privacy_and_are_committed_to_protecti', 'ru', 'Добро пожаловать в Amara. Мы уважаем твою конфиденциальность и обязуемся защищать твои персональные данные. Эта политика конфиденциальности расскажет, как мы заботимся о твоих данных, когда ты посещаешь наше приложение, и о твоих правах на конфиденциальность и защите по закону.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.privacypolicyscreen.personal_data_means_any_information_about_an_individual_from_which_tha', 'ru', 'Персональные данные — это любая информация о человеке, по которой его можно идентифицировать. •') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
