INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_the_woman_receives_your_invitation_she_reviews_your_profile_photo', 'zh', '当女性收到你的邀请时，她会查看你的资料、照片和约会提议。只有她可以决定接受或拒绝。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.no_endless_in_app_small_talk_once_she_accepts_both_of_your_telegram_ha', 'zh', '无尽的站内闲聊！一旦她接受，你们的 Telegram 用户名将被安全解锁，方便你们聊天并直接安排约会。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
