INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.say_goodbye_to_hundreds_of_unwanted_messages_men_cannot_message_you_di', 'zh', '告别数百条骚扰信息。男性无法直接给你发消息；他们只能发送正式的约会邀请供你审核。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.invitations_arrive_in_your_requests_inbox_review_their_verified_profil', 'zh', '邀请会出现在你的请求收件箱中。查看他们经过验证的资料、照片和背景。由你决定想见谁。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
