INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_follows_a_private_luxury_model_many_successful_ambitious_men_val', 'zh', 'Amara 采用私密奢华模式。许多成功、有抱负的男性重视私密性。通过在公开动态中隐藏男性资料，你的身份将保持私密，直到你选择邀请某人。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.we_believe_dating_should_lead_to_real_life_meetings_not_endless_in_app', 'zh', '我们认为约会应该通向现实生活中的见面，而不是无尽的站内短信。一旦确认双方有意，交换 Telegram 用户名即可实现便捷、加密的直接沟通。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
