INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.your_profile_is_completely_hidden_from_the_public_feed_women_cannot_se', 'ja', 'あなたのプロフィールは公開フィードから完全に非表示になります。最初に招待を送らない限り、女性はあなたを検索したり、あなたの写真を見ることはできません。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.browse_verified_female_profiles_nearby_or_worldwide_find_someone_you_l', 'ja', '近くや世界中の認証済み女性プロフィールを閲覧しましょう。気になる人を見つけ、直接デート招待を送れます（会員登録が必要）。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_the_woman_receives_your_invitation_she_reviews_your_profile_photo', 'ja', '女性があなたの招待を受け取ると、プロフィール・写真・デートの提案を確認します。承認するか断るのは彼女自身が決めます。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.no_endless_in_app_small_talk_once_she_accepts_both_of_your_telegram_ha', 'ja', 'アプリ内の果てしない雑談は必要ありません！承認されると、二人の Telegram ユーザー名が安全に解放され、チャットやデートの手配を直接進められます。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_is_completely_free_for_all_female_members_you_will_never_be_aske', 'ja', 'Amara はすべての女性会員に完全無料です。招待、会員登録、チャットにお金を請求されることはありません。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.say_goodbye_to_hundreds_of_unwanted_messages_men_cannot_message_you_di', 'ja', '何百もの迷惑メッセージにさよならを。男性から直接メッセージは送れません。デートの正式な招待を送り、あなたが確認するだけです。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.invitations_arrive_in_your_requests_inbox_review_their_verified_profil', 'ja', '招待はリクエスト受信箱に届きます。認証済みのプロフィール・写真・経歴を確認し、会いたい相手はあなたが決めます。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.when_you_accept_an_invite_your_telegram_handle_is_shared_with_your_mat', 'ja', '招待を承認すると、あなたの Telegram ユーザー名がマッチに共有され、普段使っている場所で快適にチャットできます。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_are_mens_profiles_hidden_by_default', 'ja', 'なぜ男性のプロフィールはデフォルトで非表示なのですか？') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.why_do_matches_move_to_telegram', 'ja', 'なぜマッチは Telegram に移るのですか？') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.how_does_selfie_verification_work', 'ja', 'セルフィー認証はどう働きますか？') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.what_is_our_policy_on_sugar_dating_escorting', 'ja', 'シュガーデートや escort へのポリシーは？') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_follows_a_private_luxury_model_many_successful_ambitious_men_val', 'ja', 'Amara はプライベートなラグジュアリーモデルを採用しています。多くの成功した野心的な男性は裁量を重視します。公開フィードから男性プロフィールを隠すことで、誰かを招待するまであなたの身元はプライベートに保たれます。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.we_believe_dating_should_lead_to_real_life_meetings_not_endless_in_app', 'ja', '私たちは、出会いがアプリ内の果てしないメッセージではなく、現実の対面につながるべきだと考えています。互いの意思が確認できたら、Telegram ユーザー名を交換することで、便利で暗号化された直接的なコミュニケーションが可能になります。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.every_member_must_complete_a_real_time_selfie_verification_during_onbo', 'ja', 'すべてのメンバーは登録時にリアルタイムのセルフィー認証を完了する必要があります。これにより、すべてのプロフィールが実在の人物に属することが保証され、なりすましを排除します。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.amara_strictly_prohibits_compensated_dating_sugar_arrangements_prostit', 'ja', 'Amara は、報酬を伴う出会い、シュガー arrangements、売春、メンバー間の金銭授受を厳しく禁止しています。この基準に違反したアカウントは永久にBANされます。') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
