INSERT INTO app_translations (string_key, lang_code, translation_text) VALUES ('profile.howtousescreen.say_goodbye_to_hundreds_of_unwanted_messages_men_cannot_message_you_di', 'id', 'Ucapkan selamat tinggal pada ratusan pesan tak diinginkan. Pria tidak bisa mengirimimu pesan langsung—mereka mengirim undangan kencan formal dan kamu meninjau.') ON CONFLICT (string_key, lang_code) DO UPDATE SET translation_text = EXCLUDED.translation_text;
